insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000003','id','dewasa','Indonesia di Cincin Api','Indonesia berada di jalur pertemuan lempeng yang disebut Cincin Api Pasifik. Pertemuan lempeng inilah yang membentuk deretan gunung api dari Sumatra sampai Maluku. Saat meletus, gunung api menghasilkan beragam batuan. Lava yang membeku sangat cepat menjadi obsidian, kaca vulkanik yang hitam mengilap. Gas yang terperangkap meninggalkan banyak lubang, seperti pada batuapung dan basalt vesikuler. Gumpalan lava yang terlempar ke udara lalu membeku disebut bom gunung api.','Batuapung penuh rongga udara sehingga sangat ringan, bahkan bisa mengapung di air.','Obsidian (Bukit Rejeng, Garut), batuapung (G. Galunggung, Tasikmalaya), basalt vesikuler (Subang), bom kerak roti (Purwokerto), bom gunung api (Magelang), aliran lava') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000001','id','dewasa','Debaran Fauna Purba Indonesia','Jutaan tahun lalu, Indonesia dihuni berbagai hewan purba berukuran unik! Ada Megalochelys sp., kura-kura raksasa, hingga Elephas celebensis, gajah purba mungil dari Sulawesi. Bersama Elephas maximus dan Sinomastodon bumiayuensis, fosil-fosil ini menjadi saksi beragamnya kehidupan fauna di masa lalu. Yuk, amati dan temukan perbedaannya!','Elephas celebensis dikenal sebagai salah satu gajah purba berukuran kecil yang pernah hidup di Sulawesi.','Megalochelys sp., Elephas celebensis, Elephas maximus, Sinomastodon bumiayuensis') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000002','id','dewasa','Rahasia Dunia Karst Indonesia','Pernah melihat gua dengan hiasan batu yang menjuntai dari langit-langitnya? Itulah salah satu keunikan kawasan karst, seperti Gunung Sewu, yang terbentuk melalui proses pelarutan batuan kapur selama waktu yang sangat lama. Yuk, amati stalaktit, sinter kapur, batu jahe, hingga berbagai jenis batuan dan terumbu karang untuk mengenal keindahan proses pembentukan alam!','Stalaktit terbentuk dari endapan mineral kalsit yang menumpuk perlahan dari tetesan air di langit-langit gua.','Karst Gunung Sewu, stalaktit kalsit, batugamping, batu jahe, sinter kapur, marmer, amfibolit, hasil karstifikasi, hard coral, plate coral, branching coral, head coral') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000004','id','dewasa','Kisah Terbentuknya Muka Bumi Indonesia','Tahukah kamu bahwa bentuk muka bumi Indonesia terbentuk melalui proses geologi selama jutaan tahun? Pergerakan dan tekanan lempeng bumi menghasilkan berbagai struktur batuan, seperti lipatan dan sesar. Yuk, amati koleksi genes, sekis biotit, serta contoh struktur geologi untuk melihat bagaimana bumi terus berubah!','Lipatan terbentuk ketika lapisan batuan mendapat tekanan hingga melengkung tanpa terpecah.','Genes, sekis biotit, lipatan, sesar') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000005','id','dewasa','Perjalanan Lahirnya Kepulauan Indonesia','Pernah penasaran bagaimana ribuan pulau di Indonesia terbentuk? Melalui animasi ini, kamu bisa mengikuti perjalanan terbentuknya Kepulauan Indonesia akibat pergerakan lempeng tektonik, aktivitas gunung api, dan proses geologi selama jutaan tahun. Yuk, saksikan bagaimana daratan yang awalnya terpisah akhirnya membentuk Indonesia seperti yang kita kenal sekarang!','Bentuk kepulauan Indonesia terus mengalami perubahan akibat aktivitas tektonik hingga saat ini.','video') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000006','id','dewasa','Bagaimana Wajah Bumi Terbentuk?','Bentuk permukaan bumi yang kita lihat sekarang terbentuk melalui proses alam selama ribuan hingga jutaan tahun. Pelapukan menghancurkan batuan, erosi memindahkan material, sedangkan pengendapan menumpuknya di tempat baru. Yuk, amati contoh bentukan muka bumi dan cari tahu bagaimana ketiga proses ini mengubah lanskap Indonesia!','Material hasil erosi dapat terbawa air, angin, maupun es sebelum akhirnya mengendap di tempat lain.','Sembulan bentukan morfologi muka bumi, pelapukan, erosi, dan pengendapan') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000007','id','dewasa','Mengenal Harta Karun Bumi: Batuan dan Mineral','Bumi menyimpan beragam mineral dan batuan dengan warna, bentuk, serta karakteristik yang berbeda! Ada lapis lazuli yang terkenal dengan warna biru pekatnya, hingga geodes yang menyimpan kristal di bagian dalamnya. Yuk, amati berbagai koleksi mineral dan kenali tiga kelompok utama batuan: beku, sedimen, dan metamorf!','eodes dapat terlihat seperti batu biasa dari luar, tetapi bagian dalamnya bisa dipenuhi kristal yang indah.','Lapis lazuli, mineral hidroksida, oksida, silikat, karbonat, borat dan nitrat, unsur asli (native elements), sulfida, fosfat, sulfat, batuan beku, batuan sedimen, batuan metamorf, geodes') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000008','id','dewasa','Kekuatan Tersembunyi di Dalam Bumi','Permukaan bumi yang kita pijak ternyata terus bergerak! Tenaga tektonik berasal dari pergerakan lempeng bumi yang dapat membentuk pegunungan, lipatan, hingga patahan. Yuk, amati koleksi sekis mika, peridotit, dan lava basal untuk mengenal lebih jauh proses yang membentuk bumi!','Peridotit merupakan batuan yang banyak menyusun bagian mantel atas bumi.','Proses terjadinya tenaga tektonik, sekis mika, peridotit, lava basal') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000009','id','dewasa','Dari Big Bang hingga Terbentuknya Bumi','Pernah membayangkan bagaimana alam semesta dan planet Bumi terbentuk? Menurut teori Big Bang, alam semesta bermula dari kondisi yang sangat panas dan padat, lalu terus mengembang hingga sekarang. Seiring waktu, Bumi terbentuk dan mengalami perubahan struktur serta bentuk hingga menjadi planet yang kita kenal saat ini. Yuk, ikuti perjalanan panjang Bumi melalui koleksi dan ilustrasi di hadapanmu!','Bumi memiliki empat lapisan utama, yaitu kerak, mantel, inti luar, dan inti dalam.','Teori Big Bang, hamparan luas alam semesta, proses terbentuknya planet Bumi, penampang struktur Bumi, perkembangan bentuk Bumi') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000010','id','dewasa','Ragam Batuan dari Nusantara','Indonesia memiliki beragam jenis batuan yang terbentuk melalui proses geologi yang berbeda-beda. Mulai dari batugamping hitam, sekis biotit, rijang, peridotit, hingga granit, setiap batuan menyimpan cerita tentang proses pembentukan bumi. Yuk, amati warna dan tekstur koleksinya, lalu temukan perbedaannya!','Granit terbentuk dari magma yang mendingin secara perlahan di bawah permukaan bumi sehingga kristalnya dapat terlihat jelas.','Batugamping hitam, sekis biotit, rijang, peridotit, batuan granit') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000011','id','dewasa','Kekayaan Indonesia','Indonesia menyimpan kekayaan geologi yang melimpah, mulai dari mineral logam, mineral non-logam, hingga batu mulia seperti ametis dari Solok, Sumatera Barat. Selain itu, ada batubara, minyak dan gas bumi, panas bumi, serta sumber daya air yang dimanfaatkan untuk kehidupan sehari-hari. Yuk, kenali berbagai potensi alam ini dan bagaimana manusia memanfaatkannya!','Indonesia memiliki potensi panas bumi yang besar karena berada di kawasan dengan aktivitas vulkanik tinggi.','Batubara, mineral logam, mineral non-logam, batu mulia (ametis), minyak dan gas bumi, panas bumi (geothermal), sumber daya air dan cekungan air tanah') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000001','id','anak','Yuk, Kenalan dengan Hewan Purba Indonesia!','Jutaan tahun lalu, Indonesia dihuni banyak hewan purba yang unik! Ada Megalochelys sp., si kura-kura raksasa. Ada juga Elephas celebensis, gajah purba mungil dari Sulawesi. Bersama Elephas maximus dan Sinomastodon bumiayuensis, fosil-fosil ini menjadi saksi beragamnya hewan di masa lalu. Ayo amati dan temukan perbedaannya!','Tahukah kamu? Elephas celebensis adalah salah satu gajah purba berukuran kecil yang pernah hidup di Sulawesi.','Megalochelys sp., Elephas celebensis, Elephas maximus, Sinomastodon bumiayuensis') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000002','id','anak','Rahasia Gua dan Karst','Pernah melihat gua dengan hiasan batu yang menjuntai dari langit-langitnya? Itu salah satu keunikan kawasan karst, seperti Gunung Sewu! Karst terbentuk saat batuan kapur larut perlahan selama waktu yang sangat lama. Ayo amati stalaktit, sinter kapur, batu jahe, berbagai jenis batuan, dan terumbu karang!','Tahukah kamu? Stalaktit terbentuk dari endapan mineral kalsit yang menumpuk sedikit demi sedikit dari tetesan air di langit-langit gua.','Karst Gunung Sewu, stalaktit kalsit, batugamping, batu jahe, sinter kapur, marmer, amfibolit, hasil karstifikasi, hard coral, plate coral, branching coral, head coral') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000003','id','anak','Indonesia di Cincin Api','Tahukah kamu? Indonesia berada di jalur pertemuan lempeng yang disebut Cincin Api Pasifik. Pertemuan lempeng ini membentuk deretan gunung api dari Sumatra sampai Maluku. Ayo lihat peta di depanmu, lalu temukan gunung api yang paling dekat dengan Bandung!','Deretan gunung api dari Sumatra sampai Maluku terbentuk karena pertemuan lempeng di jalur Cincin Api Pasifik.','Peta sebaran gunung api') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000004','id','anak','Bumi yang Terus Berubah','Tahukah kamu? Bentuk muka bumi Indonesia terbentuk lewat proses geologi selama jutaan tahun! Pergerakan dan tekanan lempeng bumi menghasilkan struktur batuan, seperti lipatan dan sesar. Yuk, amati genes, sekis biotit, dan contoh struktur geologi untuk melihat bagaimana bumi terus berubah!','Lipatan terbentuk saat lapisan batuan ditekan sampai melengkung, tanpa terpecah.','Genes, sekis biotit, lipatan, sesar') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000005','id','anak','Lahirnya Kepulauan Indonesia','Pernah penasaran bagaimana ribuan pulau di Indonesia terbentuk? Lewat animasi ini, kamu bisa mengikuti perjalanannya! Pulau-pulau itu terbentuk karena pergerakan lempeng tektonik, aktivitas gunung api, dan proses geologi selama jutaan tahun. Yuk, saksikan bagaimana daratan yang awalnya terpisah akhirnya membentuk Indonesia seperti sekarang!','Bentuk kepulauan Indonesia masih terus berubah sampai sekarang karena aktivitas tektonik.','video') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000006','id','anak','Tiga Pembentuk Wajah Bumi','Bentuk permukaan bumi yang kita lihat sekarang terbentuk lewat proses alam selama ribuan hingga jutaan tahun. Ada tiga proses yang bekerja. Pelapukan menghancurkan batuan, erosi memindahkan material, dan pengendapan menumpuknya di tempat baru. Yuk, amati contoh bentukan muka bumi dan lihat bagaimana ketiganya mengubah lanskap Indonesia!','Material hasil erosi bisa terbawa air, angin, atau es sebelum akhirnya mengendap di tempat lain.','Bentukan morfologi muka bumi, pelapukan, erosi, dan pengendapan') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000007','id','anak','Harta Karun Bumi: Batuan dan Mineral','Bumi menyimpan banyak mineral dan batuan dengan warna dan bentuk yang berbeda-beda! Ada lapis lazuli yang terkenal dengan warna biru pekatnya. Ada juga geodes yang menyimpan kristal di bagian dalamnya. Yuk, amati koleksi mineralnya dan kenali tiga kelompok utama batuan: beku, sedimen, dan metamorf!','Geodes bisa terlihat seperti batu biasa dari luar, tetapi bagian dalamnya bisa dipenuhi kristal yang indah.','Lapis lazuli, mineral hidroksida, oksida, silikat, karbonat, borat dan nitrat, unsur asli (native elements), sulfida, fosfat, sulfat, batuan beku, batuan sedimen, batuan metamorf, geodes') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000008','id','anak','Bumi yang Tidak Pernah Diam','Tahukah kamu? Permukaan bumi yang kita pijak ternyata terus bergerak! Tenaga tektonik berasal dari pergerakan lempeng bumi, yang bisa membentuk pegunungan, lipatan, dan patahan. Yuk, amati sekis mika, peridotit, dan lava basal untuk mengenal proses yang membentuk bumi!','Peridotit adalah batuan yang banyak menyusun bagian mantel atas bumi.','Proses terjadinya tenaga tektonik, sekis mika, peridotit, lava basal') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000009','id','anak','Dari Big Bang sampai Bumi Terbentuk','Pernah membayangkan bagaimana alam semesta dan planet Bumi terbentuk? Menurut teori Big Bang, alam semesta bermula dari kondisi yang sangat panas dan padat, lalu terus mengembang sampai sekarang. Seiring waktu, Bumi terbentuk dan berubah hingga menjadi planet yang kita kenal. Yuk, ikuti perjalanan panjang Bumi lewat koleksi dan ilustrasi di depanmu!','Bumi punya empat lapisan utama, yaitu kerak, mantel, inti luar, dan inti dalam.','Teori Big Bang, hamparan luas alam semesta, proses terbentuknya planet Bumi, penampang struktur Bumi, perkembangan bentuk Bumi') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000010','id','anak','Batuan dari Nusantara','Indonesia punya banyak jenis batuan yang terbentuk lewat proses geologi yang berbeda-beda. Ada batugamping hitam, sekis biotit, rijang, peridotit, dan granit. Setiap batuan menyimpan cerita tentang proses pembentukan bumi. Yuk, amati warna dan tekstur koleksinya, lalu temukan perbedaannya!','Granit terbentuk dari magma yang mendingin perlahan di bawah permukaan bumi, sehingga kristalnya terlihat jelas.','Batugamping hitam, sekis biotit, rijang, peridotit, batuan granit') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.konten(id_poi,bahasa,profil,judul_cerita,teks_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000011','id','anak','Harta Kekayaan Indonesia','Indonesia menyimpan kekayaan geologi yang melimpah! Ada mineral logam, mineral non-logam, dan batu mulia seperti ametis dari Solok, Sumatera Barat. Ada juga batubara, minyak dan gas bumi, panas bumi, serta sumber daya air yang dimanfaatkan untuk kehidupan sehari-hari. Yuk, kenali kekayaan alam ini dan bagaimana manusia memanfaatkannya!','Indonesia punya potensi panas bumi yang besar karena berada di kawasan dengan aktivitas vulkanik yang tinggi.','Batubara, mineral logam, mineral non-logam, batu mulia (ametis), minyak dan gas bumi, panas bumi (geothermal), sumber daya air dan cekungan air tanah') on conflict (id_poi,bahasa,profil) do update set judul_cerita=excluded.judul_cerita,teks_cerita=excluded.teks_cerita,fakta_menarik=excluded.fakta_menarik,koleksi_sorotan=excluded.koleksi_sorotan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','foto') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000001','id','dewasa','Serpihan kura-kura raksasa','Sebutkan ada binatang apa saja yang terdapat fosilnya','Fosilnya merupakan cangkang','Terdapat bagian dari kura-kura raksasa disini,cari dan foto',NULL,ARRAY['1'],'Cangkang kura-kura raksasa seperti Megalochelys sp. adalah salah satu bukti beragamnya fauna purba Indonesia yang dipamerkan di POI ini.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','pilgan') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000002','id','dewasa','Tetesan dari Langit-Langit Gua','Di gua karst, tetesan air kaya kalsit perlahan membentuk hiasan batu yang menjuntai dari langit-langit gua. Perhatikan koleksi di POI ini, lalu pilih: apa nama hiasan batu tersebut?','Ia tumbuh ke bawah dari langit-langit gua, bukan naik dari lantai.',NULL,NULL,NULL,'Stalaktit terbentuk dari endapan mineral kalsit yang menumpuk perlahan dari tetesan air di langit-langit gua.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
