insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000003','id','dewasa','Cari Gunung Api Terdekat Bandung','Indonesia berada di Cincin Api Pasifik, jalur pertemuan lempeng yang melahirkan deretan gunung api dari Sumatra sampai Maluku. Temukan peta sebaran gunung api, lalu foto bagian peta yang menunjukkan gunung api paling dekat dengan Bandung!','Fokuskan pandanganmu ke Pulau Jawa, lalu cari titik gunung api di sekitar Bandung.','Peta sebaran gunung api terlihat jelas, dengan area Pulau Jawa di dalam bingkai',NULL,NULL,'Pertemuan lempeng di jalur Cincin Api Pasifik membentuk deretan gunung api dari Sumatra sampai Maluku.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000004','benar_salah') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000004','id','dewasa','Lipatan atau Sesar?','Amati contoh struktur geologi di POI ini, lalu jawab: Benar atau Salah? "Batuan yang melengkung tanpa terpecah akibat tekanan disebut sesar."','Sesar itu patahan. Struktur yang melengkung punya nama lain.',NULL,NULL,NULL,'Salah. Batuan yang melengkung tanpa terpecah disebut lipatan, sedangkan sesar terbentuk ketika batuan patah dan bergeser.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
