insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000005','30000000-0000-4000-8000-000000000005','isian_singkat') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000005','id','dewasa','Menonton Kelahiran Nusantara','Tonton animasi terbentuknya Kepulauan Indonesia sampai selesai. Lalu lengkapi kalimat ini dengan satu kata: "Pergerakan lempeng ..... bersama aktivitas gunung api membentuk ribuan pulau di Indonesia."','Dengarkan narasi tentang lempeng bumi yang terus bergerak.',NULL,'tektonik',ARRAY['tektonik','lempeng tektonik','Tektonik'],'Pergerakan lempeng tektonik, aktivitas gunung api, dan proses geologi selama jutaan tahun membentuk Kepulauan Indonesia, dan bentuknya masih terus berubah hingga kini.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000006','30000000-0000-4000-8000-000000000006','cocokkan') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000006','id','dewasa','Trio Pembentuk Lanskap','Tiga proses bekerja mengubah wajah bumi: 1) Pelapukan, 2) Erosi, 3) Pengendapan. Peran mereka: A) memindahkan material lewat air, angin, atau es; B) menumpuk material di tempat baru; C) menghancurkan batuan. Pilih pasangan yang tepat!','Urutan kerjanya: batuan hancur dulu, lalu berpindah, lalu menetap.',NULL,NULL,NULL,'Pelapukan menghancurkan batuan, erosi memindahkan material hasil pelapukan lewat air, angin, atau es, dan pengendapan menumpuknya di tempat baru.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
