insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000007','30000000-0000-4000-8000-000000000007','foto') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000007','id','dewasa','Temukan Si Biru Pekat','Di antara koleksi mineral, ada batu dengan warna biru pekat yang terkenal: lapis lazuli. Temukan dan foto koleksinya bersama label namanya!','Cari batu berwarna biru tua yang mencolok di etalase mineral.','Koleksi lapis lazuli (biru pekat) dengan label nama terbaca',NULL,NULL,'Lapis lazuli terkenal dengan warna biru pekatnya dan menjadi salah satu koleksi mineral di POI ini.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000008','30000000-0000-4000-8000-000000000008','isian_singkat') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000008','id','dewasa','Penghuni Mantel Bumi','Tenaga tektonik berasal dari pergerakan lempeng bumi. Di antara sekis mika, peridotit, dan lava basal, batuan manakah yang banyak menyusun bagian mantel atas bumi?','Ia berasal dari lapisan di bawah kerak bumi. Cek label koleksinya!',NULL,'Peridotit',ARRAY['peridotit','batuan peridotit'],'Peridotit merupakan batuan yang banyak menyusun bagian mantel atas bumi.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000009','30000000-0000-4000-8000-000000000009','pilgan') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000009','id','dewasa','Menembus Lapisan Bumi','Bumi punya empat lapisan utama. Perhatikan ilustrasi penampang struktur Bumi, lalu pilih urutan lapisan dari yang paling luar sampai paling dalam.','Kerak adalah "kulit" bumi tempat kita berpijak.',NULL,NULL,NULL,'Bumi memiliki empat lapisan utama, yaitu kerak, mantel, inti luar, dan inti dalam.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
