insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000010','30000000-0000-4000-8000-000000000010','foto') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000010','id','dewasa','Detektif Tekstur Batuan','Setiap batuan punya warna dan tekstur sendiri. Temukan dua batuan berbeda di etalase (misalnya granit dan batugamping hitam), lalu foto keduanya dalam satu bingkai sehingga perbedaan warna dan teksturnya terlihat!','Granit memiliki kristal yang terlihat jelas. Bandingkan dengan batuan berwarna gelap.','Dua koleksi batuan berbeda dalam satu foto, label nama terbaca',NULL,NULL,'Granit terbentuk dari magma yang mendingin perlahan di bawah permukaan bumi sehingga kristalnya terlihat jelas. Tiap batuan menyimpan cerita pembentukan yang berbeda.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
insert into public.quest(id_quest,id_poi,tipe_quest) values ('40000000-0000-4000-8000-000000000011','30000000-0000-4000-8000-000000000011','pilgan') on conflict (id_poi) do update set tipe_quest=excluded.tipe_quest;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,kunci_isian,variasi_jawaban,penjelasan) values ('40000000-0000-4000-8000-000000000011','id','dewasa','Ametis dari Tanah Minang','Indonesia kaya sumber daya geologi, termasuk batu mulia berwarna ungu. Berdasarkan cerita pameran, ametis berasal dari daerah mana?','Daerah asalnya berada di Pulau Sumatra.',NULL,NULL,NULL,'Ametis adalah batu mulia yang berasal dari Solok, Sumatera Barat, bagian dari kekayaan geologi Indonesia.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,kunci_isian=excluded.kunci_isian,variasi_jawaban=excluded.variasi_jawaban,penjelasan=excluded.penjelasan;
