insert into public.quest_opsi(id_quest,label_opsi,is_correct) values ('40000000-0000-4000-8000-000000000011','D',false) on conflict (id_quest,label_opsi) do update set is_correct=excluded.is_correct;
insert into public.quest_opsi_text(id_quest,label_opsi,bahasa,teks_opsi) values ('40000000-0000-4000-8000-000000000011','D','id','Ternate, Maluku Utara') on conflict (id_quest,label_opsi,bahasa) do update set teks_opsi=excluded.teks_opsi;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,penjelasan) values ('40000000-0000-4000-8000-000000000001','id','anak','Cari Cangkang Kura-Kura Raksasa!','Hewan apa saja yang fosilnya ada di sini? Pilih jawabanmu, lalu cari dan foto fosil kura-kura raksasa!','Cari fosil berbentuk cangkang, ya!','Bagian fosil kura-kura raksasa (cangkang) terlihat jelas di dalam foto','Hebat! Cangkang kura-kura raksasa seperti Megalochelys sp. adalah bukti beragamnya hewan purba Indonesia yang dipamerkan di sini.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,penjelasan=excluded.penjelasan;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,penjelasan) values ('40000000-0000-4000-8000-000000000003','id','anak','Cari Gunung Api Terdekat dari Bandung!','Ayo cari peta sebaran gunung api! Lalu foto bagian peta yang menunjukkan gunung api paling dekat dengan Bandung, ya!','Lihat Pulau Jawa dulu, lalu cari titik gunung api di sekitar Bandung.','Peta sebaran gunung api terlihat jelas, dengan area Pulau Jawa di dalam foto','Keren! Pertemuan lempeng di jalur Cincin Api Pasifik membentuk deretan gunung api dari Sumatra sampai Maluku.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,penjelasan=excluded.penjelasan;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,penjelasan) values ('40000000-0000-4000-8000-000000000007','id','anak','Temukan Si Biru Tua!','Yuk, cari batu biru tua bernama lapis lazuli di antara koleksi mineral! Foto batunya bersama label namanya, ya!','Cari batu berwarna biru tua yang mencolok di etalase mineral.','Lapis lazuli (biru pekat) terlihat jelas bersama label nama yang bisa dibaca','Hore, ketemu! Lapis lazuli terkenal dengan warna biru pekatnya dan menjadi salah satu koleksi mineral di sini.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,penjelasan=excluded.penjelasan;
insert into public.quest_teks(id_quest,bahasa,profil,instruksi,pertanyaan,hint,target_foto,penjelasan) values ('40000000-0000-4000-8000-000000000010','id','anak','Detektif Cilik: Warna dan Tekstur Batuan','Setiap batuan punya warna dan tekstur sendiri. Ayo cari dua batuan berbeda di etalase, misalnya granit dan batugamping hitam! Foto keduanya dalam satu foto, ya, supaya beda warna dan teksturnya kelihatan!','Granit punya kristal yang terlihat jelas. Bandingkan dengan batuan yang warnanya gelap!','Dua batuan berbeda terlihat dalam satu foto, dengan label nama yang bisa dibaca','Mantap! Granit terbentuk dari magma yang mendingin perlahan di bawah permukaan bumi, jadi kristalnya terlihat jelas. Setiap batuan punya cerita pembentukan yang berbeda.') on conflict (id_quest,bahasa,profil) do update set instruksi=excluded.instruksi,pertanyaan=excluded.pertanyaan,hint=excluded.hint,target_foto=excluded.target_foto,penjelasan=excluded.penjelasan;
